public class Driver { interface Shape{double area();String label();} record Circle(double r)implements Shape{public double area(){return Math.PI*r*r;}public String label(){return "Circle(r="+r+")";}} record Rectangle(double w,double h)implements Shape{public double area(){return w*h;}public String label(){return "Rectangle("+w+"x"+h+")";}}public static void main(String[]a){Shape[] s={new Circle(5),new Rectangle(4,6)};double total=0;for(Shape x:s){total+=x.area();System.out.printf("%-18s Area: %.2f%n",x.label(),x.area());}System.out.printf("Total Area: %.2f%n",total);}}
